components.css:
.ds-button-primary { display: inline-flex;
  align-items: center;
  gap: 10px;
  min-height: 44px;
  padding: 9px 17px;
  border: 1px solid transparent;
  border-radius: var(--dp-radius-pill, 999px);
  font-size: .875rem;
  font-weight: 550;
  transition: background var(--dp-motion-duration, 120ms) var(--dp-motion-ease, ease-out), border-color var(--dp-motion-duration, 120ms) var(--dp-motion-ease, ease-out); font-family: var(--dp-typography-face, Geist, 'Helvetica Neue', Arial, sans-serif); line-height: 1.55; cursor: pointer; }
.ds-button-primary { background: var(--dp-color-bright, #f2f2f2); color: var(--dp-color-inverse-ink, #0a0a0a);  }
.ds-button-primary:hover:not(:disabled) { background: #cfd8de;  }
.ds-button-primary:disabled { background: #242424; color: var(--dp-color-read, #a6a9ad); border-color: var(--dp-color-hairline-2, #303030);  }
.ds-focus:focus-visible { outline: 2px solid var(--brand-focus, #70d7ff); outline-offset: 4px; }
@media (prefers-reduced-motion: reduce) { .ds-button-primary { transition: none; } }

.ds-button-secondary { display: inline-flex;
  align-items: center;
  gap: 10px;
  min-height: 44px;
  padding: 9px 17px;
  border: 1px solid transparent;
  border-radius: var(--dp-radius-pill, 999px);
  font-size: .875rem;
  font-weight: 550;
  transition: background var(--dp-motion-duration, 120ms) var(--dp-motion-ease, ease-out), border-color var(--dp-motion-duration, 120ms) var(--dp-motion-ease, ease-out); font-family: var(--dp-typography-face, Geist, 'Helvetica Neue', Arial, sans-serif); line-height: 1.55; cursor: pointer; }
.ds-button-secondary { color: var(--dp-color-bright, #f2f2f2); background: var(--dp-color-panel, #0e0e0e); border-color: #626262;  }
.ds-button-secondary:hover:not(:disabled) { background: #242424; border-color: #686868;  }
.ds-button-secondary:disabled { background: #242424; color: var(--dp-color-read, #a6a9ad); border-color: var(--dp-color-hairline-2, #303030);  }
.ds-focus:focus-visible { outline: 2px solid var(--brand-focus, #70d7ff); outline-offset: 4px; }
@media (prefers-reduced-motion: reduce) { .ds-button-secondary { transition: none; } }

.ds-field { display: grid; gap: 8px; color: var(--dp-color-bright, #f2f2f2); font: 16px/1.55 var(--dp-typography-face, Geist, 'Helvetica Neue', Arial, sans-serif); font-size: .875rem; }
.ds-field input { width: 100%;
  min-height: 46px;
  border: 1px solid #626262;
  border-radius: var(--dp-radius-panel, 6px);
  padding: 8px 12px;
  color: var(--dp-color-bright, #f2f2f2);
  caret-color: var(--brand-focus, #70d7ff);
  background: var(--dp-color-ground, #050505); font: 16px/1.55 var(--dp-typography-face, Geist, 'Helvetica Neue', Arial, sans-serif); }
.ds-field input::placeholder { color: var(--dp-color-meta, #8a8d91);  }
.ds-focus:focus-visible { outline: 2px solid var(--brand-focus, #70d7ff); outline-offset: 4px; }

.ds-upload { display: flex;
  align-items: center;
  gap: var(--dp-spacing-gap, 24px);
  margin-block: 32px 46px;
  padding: 24px;
  border: 1px solid var(--dp-color-hairline-2, #303030);
  border-radius: var(--dp-radius-panel, 6px);
  background: var(--dp-color-panel, #0e0e0e); font: 16px/1.55 var(--dp-typography-face, Geist, 'Helvetica Neue', Arial, sans-serif); margin: 0; color: var(--dp-color-bright, #f2f2f2); }
.ds-upload h2 { margin: 0; font-size: 1.2rem; font-weight: 450; line-height: 1.12; letter-spacing: -.025em; }
.ds-upload p { margin-top: 5px; margin-bottom: 0; color: var(--dp-color-read, #a6a9ad); }

.ds-upload-list { border-top: 1px solid var(--dp-color-hairline, #222);  }
.ds-upload-list { border-bottom: 1px solid var(--dp-color-hairline, #222);  }
.ds-upload-row { display: grid;
  width: 100%;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 12px;
  text-align: start;
  padding: 12px 8px;
  border: 0;
  background: transparent;
  color: var(--dp-color-read, #a6a9ad); font: 16px/1.55 var(--dp-typography-face, Geist, 'Helvetica Neue', Arial, sans-serif); cursor: pointer; }
.ds-upload-row:hover, .ds-upload-row[aria-current] { background: var(--dp-color-panel, #0e0e0e);  }
.ds-upload-row[aria-current] .ds-row-arrow { color: var(--dp-color-live, #3fd6c6);  }
.ds-row-copy { overflow-wrap: anywhere;  }
.ds-row-copy strong { display: block; color: var(--dp-color-bright, #f2f2f2); font-weight: 500;  }
.ds-row-meta { font-family: var(--dp-typography-mono, 'Geist Mono', Menlo, monospace); font-size: .8125rem;  }
.ds-focus:focus-visible { outline: 2px solid var(--brand-focus, #70d7ff); outline-offset: 4px; }

.ds-status { display: flex; align-items: center; gap: 8px; font: 16px/1.55 var(--dp-typography-face, Geist, 'Helvetica Neue', Arial, sans-serif); margin: 0; color: var(--dp-color-read, #a6a9ad); }
.ds-status::before { content: ''; width: 7px; height: 7px; border-radius: var(--dp-radius-pill, 999px); background: currentColor;  }
.ds-status[data-status="ready"]::before { color: var(--dp-color-live, #3fd6c6);  }
.ds-status[data-status="failed"]::before { color: var(--error, #ffada7);  }

.ds-markdown { margin-block: 14px;
  padding: 18px;
  background: var(--dp-color-panel, #0e0e0e);
  border-radius: var(--dp-radius-panel, 6px);
  color: var(--dp-color-bright, #f2f2f2);
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  font: .875rem/1.65 var(--dp-typography-mono, 'Geist Mono', Menlo, monospace); margin: 0; }
